-- Immutable versions, tenant-scoped foreign keys, and deny-by-default client writes.
create type public.app_role as enum ('platform_admin','school_admin','teacher','examiner','viewer');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null default '', created_at timestamptz not null default now());
create table public.platform_admins (user_id uuid primary key references auth.users(id) on delete cascade);
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 1 and 150), created_by uuid not null references auth.users(id), created_at timestamptz not null default now());
create table public.organization_members (organization_id uuid not null references public.organizations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role public.app_role not null check(role <> 'platform_admin'), primary key(organization_id,user_id));
create table public.organization_invitations (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), role public.app_role not null check(role <> 'platform_admin'), created_by uuid not null references auth.users(id), expires_at timestamptz not null default now()+interval '7 days', accepted_by uuid references auth.users(id), accepted_at timestamptz);
create table public.classes (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), name text not null check(length(name) between 1 and 80), year text not null check(length(year) between 1 and 30), created_by uuid not null references auth.users(id), unique(organization_id,id), unique(organization_id,name,year));
create table public.class_members (organization_id uuid not null, class_id uuid not null, user_id uuid not null, primary key(class_id,user_id), foreign key(organization_id,class_id) references public.classes(organization_id,id), foreign key(organization_id,user_id) references public.organization_members(organization_id,user_id));
create table public.students (id uuid primary key default gen_random_uuid(), organization_id uuid not null, class_id uuid not null, number text not null check(number ~ '^\d{1,12}$'), name text not null check(length(trim(name)) between 1 and 150), created_by uuid not null references auth.users(id), foreign key(organization_id,class_id) references public.classes(organization_id,id), unique(organization_id,number), unique(organization_id,id), unique(class_id,id));
create table public.answer_sheet_templates (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), code text not null check(code ~ '^[A-Za-z0-9_-]{1,100}$'), created_by uuid not null references auth.users(id), unique(organization_id,id), unique(organization_id,code));
create table public.template_versions (id uuid primary key default gen_random_uuid(), organization_id uuid not null, template_id uuid not null, version integer not null check(version>0), config jsonb not null, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), foreign key(organization_id,template_id) references public.answer_sheet_templates(organization_id,id), unique(template_id,version), unique(organization_id,id));
create table public.exams (id uuid primary key default gen_random_uuid(), organization_id uuid not null, class_id uuid not null, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), foreign key(organization_id,class_id) references public.classes(organization_id,id), unique(organization_id,id), unique(class_id,id));
create table public.exam_versions (id uuid primary key default gen_random_uuid(), organization_id uuid not null, exam_id uuid not null, version integer not null check(version>0), template_version_id uuid not null, exam_date date not null, document jsonb not null, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), foreign key(organization_id,exam_id) references public.exams(organization_id,id), foreign key(organization_id,template_version_id) references public.template_versions(organization_id,id), unique(exam_id,version), unique(organization_id,id));
create table public.exam_codes (id uuid primary key default gen_random_uuid(), organization_id uuid not null, exam_version_id uuid not null, code text not null, foreign key(organization_id,exam_version_id) references public.exam_versions(organization_id,id), unique(exam_version_id,code), unique(organization_id,id));
create table public.exam_questions (id uuid primary key default gen_random_uuid(), organization_id uuid not null, exam_code_id uuid not null, number integer not null check(number>0), section_title text not null, choices integer not null check(choices between 2 and 5), foreign key(organization_id,exam_code_id) references public.exam_codes(organization_id,id), unique(exam_code_id,number), unique(organization_id,id));
create table public.answer_keys (organization_id uuid not null, question_id uuid primary key, correct_answer text not null check(correct_answer in ('A','B','C','D','E')), points numeric not null check(points>0), foreign key(organization_id,question_id) references public.exam_questions(organization_id,id));
create table public.grading_rules (id uuid primary key default gen_random_uuid(), organization_id uuid not null, exam_version_id uuid not null unique, config jsonb not null default '{"type":"weighted_mcq","blank":0,"multiple":0,"rounding":4}', foreign key(organization_id,exam_version_id) references public.exam_versions(organization_id,id), unique(organization_id,id));
create table public.exam_assignments (organization_id uuid not null, exam_id uuid not null, user_id uuid not null, assigned_by uuid not null references auth.users(id), primary key(exam_id,user_id), foreign key(organization_id,exam_id) references public.exams(organization_id,id), foreign key(organization_id,user_id) references public.organization_members(organization_id,user_id));
create table public.exam_submissions (id uuid primary key, organization_id uuid not null, exam_id uuid not null, exam_version_id uuid not null, template_version_id uuid not null, grading_rule_id uuid not null, student_id uuid not null, class_id uuid not null, exam_code text not null, state text not null default 'uploading' check(state in ('uploading','complete')), score numeric, max_score numeric not null, original_path text not null unique, processed_path text not null unique, graded_by uuid not null references auth.users(id), created_at timestamptz not null default now(), completed_at timestamptz, revision integer not null default 0, foreign key(organization_id,exam_id) references public.exams(organization_id,id), foreign key(organization_id,exam_version_id) references public.exam_versions(organization_id,id), foreign key(organization_id,template_version_id) references public.template_versions(organization_id,id), foreign key(organization_id,grading_rule_id) references public.grading_rules(organization_id,id), foreign key(class_id,exam_id) references public.exams(class_id,id), foreign key(class_id,student_id) references public.students(class_id,id), unique(exam_id,student_id), unique(organization_id,id));
create table public.submission_answers (organization_id uuid not null, submission_id uuid not null, number integer not null, selected jsonb not null, state text not null, confidence numeric not null, ratios jsonb not null, reviewed boolean not null, status text not null check(status in ('correct','incorrect','blank','multiple','review')), earned numeric not null, points numeric not null, primary key(submission_id,number), foreign key(organization_id,submission_id) references public.exam_submissions(organization_id,id));
create table public.grading_history (id uuid primary key default gen_random_uuid(), organization_id uuid not null, submission_id uuid not null, revision integer not null, exam_version_id uuid not null, score numeric not null, actor uuid not null references auth.users(id), reason text not null, snapshot jsonb not null, created_at timestamptz not null default now(), foreign key(organization_id,submission_id) references public.exam_submissions(organization_id,id), foreign key(organization_id,exam_version_id) references public.exam_versions(organization_id,id), unique(submission_id,revision));
create table public.audit_logs (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), actor uuid not null references auth.users(id), action text not null, entity_id uuid, details jsonb not null default '{}', created_at timestamptz not null default now());
create table public.sheet_references (id uuid primary key default gen_random_uuid(), organization_id uuid not null, exam_id uuid not null, student_id uuid not null, exam_code text not null, created_by uuid not null references auth.users(id), foreign key(organization_id,exam_id) references public.exams(organization_id,id), foreign key(organization_id,student_id) references public.students(organization_id,id));

create index membership_user_idx on public.organization_members(user_id,organization_id);
create index class_member_user_idx on public.class_members(user_id,class_id);
create index students_class_idx on public.students(class_id);
create index exam_class_idx on public.exams(class_id);
create index assignment_user_idx on public.exam_assignments(user_id,exam_id);
create index submission_report_idx on public.exam_submissions(organization_id,exam_id,class_id,created_at);
create index submission_teacher_idx on public.exam_submissions(graded_by,created_at);
create index history_submission_idx on public.grading_history(submission_id,created_at);
create index audit_org_idx on public.audit_logs(organization_id,created_at);

create function public.is_platform_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.platform_admins where user_id=auth.uid()) $$;
create function public.org_role(p_org uuid) returns public.app_role language sql stable security definer set search_path='' as $$ select case when public.is_platform_admin() then 'platform_admin'::public.app_role else (select role from public.organization_members where organization_id=p_org and user_id=auth.uid()) end $$;
create function public.is_org_admin(p_org uuid) returns boolean language sql stable security definer set search_path='' as $$ select coalesce(public.org_role(p_org) in ('platform_admin','school_admin'),false) $$;
create function public.can_exam(p_exam uuid,p_write boolean default false) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.exams e where e.id=p_exam and (public.is_org_admin(e.organization_id) or
 (public.org_role(e.organization_id) is not null and (not p_write or public.org_role(e.organization_id) in ('teacher','examiner')) and
 (exists(select 1 from public.exam_assignments a where a.exam_id=e.id and a.user_id=auth.uid()) or
 (public.org_role(e.organization_id)='teacher' and (e.created_by=auth.uid() or exists(select 1 from public.class_members c where c.class_id=e.class_id and c.user_id=auth.uid()))))))) $$;
create function public.can_class(p_class uuid,p_write boolean default false) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.classes c where c.id=p_class and (public.is_org_admin(c.organization_id) or
 (public.org_role(c.organization_id)='teacher' and exists(select 1 from public.class_members m where m.class_id=c.id and m.user_id=auth.uid())) or
 (not p_write and exists(select 1 from public.exams e where e.class_id=c.id and public.can_exam(e.id,false))))) $$;
create function public.can_manage_exam(p_exam uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.exams e where e.id=p_exam and (public.is_org_admin(e.organization_id) or (public.org_role(e.organization_id)='teacher' and public.can_exam(e.id,true)))) $$;

-- Browser writes go exclusively through checked RPCs; policies grant read access only.
do $$ declare t text; begin foreach t in array array['profiles','platform_admins','organizations','organization_members','organization_invitations','classes','class_members','students','answer_sheet_templates','template_versions','exams','exam_versions','exam_codes','exam_questions','answer_keys','grading_rules','exam_assignments','exam_submissions','submission_answers','grading_history','audit_logs','sheet_references'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from anon, authenticated',t);
 execute format('grant select on public.%I to authenticated',t);
 end loop; end $$;
create policy profile_read on public.profiles for select to authenticated using (id=auth.uid() or exists(select 1 from public.organization_members m join public.organization_members me using(organization_id) where m.user_id=profiles.id and me.user_id=auth.uid()));
create policy platform_read on public.platform_admins for select to authenticated using(user_id=auth.uid());
create policy org_read on public.organizations for select to authenticated using(public.org_role(id) is not null);
create policy membership_read on public.organization_members for select to authenticated using(public.org_role(organization_id) is not null);
create policy invitation_read on public.organization_invitations for select to authenticated using(public.is_org_admin(organization_id));
create policy class_read on public.classes for select to authenticated using(public.can_class(id));
create policy class_members_read on public.class_members for select to authenticated using(public.can_class(class_id));
create policy student_read on public.students for select to authenticated using(public.can_class(class_id));
create policy template_read on public.answer_sheet_templates for select to authenticated using(public.org_role(organization_id) is not null);
create policy template_version_read on public.template_versions for select to authenticated using(public.org_role(organization_id) is not null);
create policy exam_read on public.exams for select to authenticated using(public.can_exam(id));
create policy version_read on public.exam_versions for select to authenticated using(public.can_exam(exam_id,true));
create policy codes_read on public.exam_codes for select to authenticated using(exists(select 1 from public.exam_versions v where v.id=exam_version_id and public.can_exam(v.exam_id,true)));
create policy questions_read on public.exam_questions for select to authenticated using(exists(select 1 from public.exam_codes c join public.exam_versions v on v.id=c.exam_version_id where c.id=exam_code_id and public.can_exam(v.exam_id,true)));
create policy keys_read on public.answer_keys for select to authenticated using(exists(select 1 from public.exam_questions q join public.exam_codes c on c.id=q.exam_code_id join public.exam_versions v on v.id=c.exam_version_id where q.id=question_id and public.can_exam(v.exam_id,true)));
create policy rules_read on public.grading_rules for select to authenticated using(exists(select 1 from public.exam_versions v where v.id=exam_version_id and public.can_exam(v.exam_id,true)));
create policy assignment_read on public.exam_assignments for select to authenticated using(public.can_exam(exam_id));
create policy submission_read on public.exam_submissions for select to authenticated using(public.can_exam(exam_id));
create policy answers_read on public.submission_answers for select to authenticated using(exists(select 1 from public.exam_submissions s where s.id=submission_id and public.can_exam(s.exam_id)));
create policy history_read on public.grading_history for select to authenticated using(exists(select 1 from public.exam_submissions s where s.id=submission_id and public.can_exam(s.exam_id)));
create policy audit_read on public.audit_logs for select to authenticated using(public.is_org_admin(organization_id));
create policy reference_read on public.sheet_references for select to authenticated using(public.can_exam(exam_id,true));

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('answer-sheets','answer-sheets',false,52428800,array['image/png']) on conflict(id) do nothing;
create policy sheet_image_read on storage.objects for select to authenticated using(bucket_id='answer-sheets' and exists(select 1 from public.exam_submissions s where name in(s.original_path,s.processed_path) and public.can_exam(s.exam_id)));
create policy sheet_image_insert on storage.objects for insert to authenticated with check(bucket_id='answer-sheets' and exists(select 1 from public.exam_submissions s where name in(s.original_path,s.processed_path) and s.graded_by=auth.uid() and s.state='uploading' and public.can_exam(s.exam_id,true)));
-- No client UPDATE/DELETE policy on images: existing evidence remains immutable.
